11	/*!
12	 * \file add_example_tiling.cpp
13	 * \brief Add算子的tiling(分块)策略实现
14	 *
15	 * 本文件提供了tiling逻辑，将大型计算任务划分为较小的块，以便在AI Core上高效并行执行。
16	 * Tiling对于最大化NPU利用率和性能至关重要。
17	 */
18	
19	#include "log/log.h"
20	#include "util/math_util.h"
21	#include "util/platform_util.h"
22	#include "op_host/tiling_util.h"
23	#include "op_host/tiling_templates_registry.h"
24	#include "examples/add_example/op_kernel/add_example_tiling_data.h"
25	#include "examples/add_example/op_kernel/add_example_tiling_key.h"
26	
27	namespace optiling {
28	
29	// 矢量系统缓冲区大小为0
30	constexpr uint32_t WS_SYS_SIZE = 0U;
31	// 输入shape的维度限制为4
32	constexpr int32_t DIMS_LIMIT = 4;
33	
34	// 维度索引常量定义
35	constexpr uint32_t INDEXZERO = 0;
36	constexpr uint32_t INDEXONE = 1;
37	constexpr uint32_t INDEXTWO = 2;
38	constexpr uint32_t INDEXTHREE = 3;
39	
40	// 缓冲区数量常量
41	constexpr int64_t BUFFER_NUM = 6;
42	// 类型大小常量(字节)
43	constexpr int64_t TYPE_SIZE = 4;
44	// 标量形状常量{1}
45	static const gert::Shape g_vec_1_shape = {1};
46	
47	// Add编译信息结构
48	struct AddExampleCompileInfo {};
49	
50	/*!
51	 * \brief 确保标量shape转换为{1}以保持一致性
52	 *
53	 * 对于标量输入，需要将其转换为1维张量以确保处理的一致性。
54	 *
55	 * \param in_shape 要检查的输入shape
56	 * \return 如果输入是标量则返回{1}，否则返回原始shape的引用
57	 */
58	inline const gert::Shape& EnsureNotScalar(const gert::Shape& in_shape)
59	{
60	    if (in_shape.IsScalar()) {
61	        return g_vec_1_shape;
62	    }
63	    return in_shape;
64	}
65	
66	/*!
67	 * \brief 获取平台信息，包括UB(统一缓冲区)大小和AI Core数量
68	 *
69	 * 该函数查询平台以获取硬件资源信息，这对于确定最优tiling策略至关重要。
70	 *
71	 * \param context 指向tiling上下文的指针
72	 * \param ubSize 输出参数：UB大小(字节)
73	 * \param coreNum 输出参数：可用的AI Core数量
74	 * \return 如果成功获取平台信息则返回ge::GRAPH_SUCCESS
75	 */
76	static ge::graphStatus GetPlatformInfo(gert::TilingContext* context, uint64_t& ubSize, int64_t& coreNum)
77	{
78	    // 获取平台信息指针
79	    fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
80	    OP_CHECK_NULL_WITH_CONTEXT(context, platformInfoPtr);
81	
82	    // 创建AscendC平台对象
83	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
84	
85	    // 获取AI Core数量
86	    coreNum = ascendcPlatform.GetCoreNumAiv();
87	    OP_CHECK_IF(coreNum == 0, OP_LOGE(context, "coreNum is 0"), return ge::GRAPH_FAILED);
88	
89	    // 获取UB(统一缓冲区)大小
90	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
91	    OP_CHECK_IF(ubSize == 0, OP_LOGE(context, "ubSize is 0"), return ge::GRAPH_FAILED);
92	
93	    return ge::GRAPH_SUCCESS;
94	}
95	
96	/*!
97	 * \brief 从输入输出张量获取shape和属性信息
98	 *
99	 * 该函数检索并验证张量shape和数据类型。它确保：
100	 * - 所有张量都有4维shape
101	 * - 数据类型是支持的(FLOAT或INT32)
102	 * - 计算总元素数量
103	 *
104	 * \param context 指向tiling上下文的指针
105	 * \param totalIdx 输出参数：要处理的元素总数
106	 * \param dataType 输出参数：输入张量的数据类型
107	 * \return 如果成功检索和验证shape信息则返回ge::GRAPH_SUCCESS
108	 */
109	ge::graphStatus GetShapeAttrsInfo(gert::TilingContext* context, int64_t& totalIdx, ge::DataType& dataType)
110	{
111	    // 获取输入x的shape信息
112	    auto inputX = context->GetInputShape(0);
113	    OP_CHECK_NULL_WITH_CONTEXT(context, inputX);
114	
115	    // 如果输入shape是标量，转换为{1}，否则保持原shape不变
116	    auto inputShapeX = EnsureNotScalar(inputX->GetStorageShape());
117	
118	    // 获取输入y的shape信息
119	    auto inputY = context->GetInputShape(1);
120	    OP_CHECK_NULL_WITH_CONTEXT(context, inputY);
121	    auto inputShapeY = EnsureNotScalar(inputY->GetStorageShape());
122	
123	    // 获取输出z的shape信息
124	    auto outZ = context->GetOutputShape(0);
125	    OP_CHECK_NULL_WITH_CONTEXT(context, outZ);
126	    auto outShapeZ = EnsureNotScalar(outZ->GetStorageShape());
127	
128	    // shape校验：确保所有张量都是4维
129	    OP_CHECK_IF(inputShapeX.GetDimNum() != DIMS_LIMIT || inputShapeY.GetDimNum() != DIMS_LIMIT ||
130	                    outShapeZ.GetDimNum() != DIMS_LIMIT,
131	                OP_LOGE(context, "AddExample: inputx,inputy,outputz shape dim = %zu, %zu, %zu, should be equal 4",
132	                        inputShapeX.GetDimNum(), inputShapeY.GetDimNum(), outShapeZ.GetDimNum()),
133	                return ge::GRAPH_FAILED);
134	
135	    // 获取shape的维度值
136	    totalIdx = inputShapeX.GetShapeSize();
137	
138	    // 数据类型校验
139	    const std::set<ge::DataType> supportedDtype = {ge::DT_FLOAT, ge::DT_INT32};
140	    auto inputDesc = context->GetInputDesc(0);
141	    OP_CHECK_NULL_WITH_CONTEXT(context, inputDesc);
142	    dataType = inputDesc->GetDataType();
143	
144	    if (supportedDtype.count(dataType) == 0) {
145	        OP_LOGE(context, "invalid dtype");
146	        return ge::GRAPH_FAILED;
147	    }
148	
149	    return ge::GRAPH_SUCCESS;
150	}
151	
152	/*!
153	 * \brief 获取算子执行所需的工作空间大小
154	 *
155	 * 工作空间是计算期间使用的额外内存。对于Add算子，
156	 * 不需要工作空间，因此大小设置为0。
157	 *
158	 * \param context 指向tiling上下文的指针
159	 * \return
160	 */
161	ge::graphStatus GetWorkspaceSize(gert::TilingContext* context)
162	{
163	    // 获取工作空间大小数组
164	    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
165	    OP_CHECK_NULL_WITH_CONTEXT(context, currentWorkspace);
166	    currentWorkspace[0] = WS_SYS_SIZE;
167	    return ge::GRAPH_SUCCESS;
168	}
169	
170	/*!
171	 * \brief Add算子的主tiling函数
172	 *
173	 * 该函数计算最优的tiling策略：
174	 * 1. 检索平台信息(UB大小、AI Core数量)
175	 * 2. 检索shape和属性信息
176	 * 3. 计算Core tiling：将工作划分到多个AI Core以实现并行
177	 * 4. 计算UB tiling：根据可用的UB内存在每个Core内划分工作
178	 * 5. 根据数据类型设置tiling key(FLOAT和INT32有不同的tiling策略)
179	 *
180	 * Tiling数据存储在AddExampleTilingData结构中，将被传递给kernel。
181	 *
182	 * \param context 指向tiling上下文的指针
183	 * \return 如果成功计算tiling策略则返回ge::GRAPH_SUCCESS
184	 */
185	static ge::graphStatus AddExampleTilingFunc(gert::TilingContext* context)
186	{
187	    // 1、获取平台运行时信息
188	    uint64_t ubSize;
189	    int64_t coreNum;
190	    OP_CHECK_IF(GetPlatformInfo(context, ubSize, coreNum) != ge::GRAPH_SUCCESS,
191	                OP_LOGE(context, "GetPlatformInfo error"), return ge::GRAPH_FAILED);
192	
193	    // 2、获取shape、属性信息
194	    int64_t totalIdx;
195	    ge::DataType dataType;
196	
197	    OP_CHECK_IF(GetShapeAttrsInfo(context, totalIdx, dataType) != ge::GRAPH_SUCCESS,
198	                OP_LOGE(context, "GetShapeAttrsInfo error"), return ge::GRAPH_FAILED);
199	
200	    // 3、获取WorkspaceSize信息
201	    OP_CHECK_IF(GetWorkspaceSize(context) != ge::GRAPH_SUCCESS, OP_LOGE(context, "GetWorkspaceSize error"),
202	                return ge::GRAPH_FAILED);
203	
204	    // 4、设置tiling信息
205	    AddExampleTilingData* tiling = context->GetTilingData<AddExampleTilingData>();
206	    OP_CHECK_NULL_WITH_CONTEXT(context, tiling);
207	
208	    // 初始化tiling数据为0
209	    OP_CHECK_IF(memset_s(tiling, sizeof(AddExampleTilingData), 0, sizeof(AddExampleTilingData)) != EOK,
210	                OP_LOGE(context, "set tiling data error"), return ge::GRAPH_FAILED);
211	
212	    // 优先做核切分，尽量用更多的核并行计算
213	    // 计算每个AI Core处理的元素数量
214	    tiling->totalNum = totalIdx;
215	    tiling->blockFactor = Ops::Base::CeilDiv(totalIdx, coreNum);
216	    int64_t usedCoreNum = Ops::Base::CeilDiv(totalIdx, tiling->blockFactor);
217	
218	    // 计算UB切分，考虑最大同时使用的UB tensor数量，计算单个UB tensor可用大小
219	    // 当前场景：2个输入和1个输出，考虑使用双缓冲，共需要6块UB tensor
220	    int64_t ubCanUse = static_cast<int64_t>(ubSize);
221	    int64_t ubBlockSize = Ops::Base::GetUbBlockSize(context);
222	    tiling->ubFactor = Ops::Base::FloorAlign(Ops::Base::FloorDiv((ubCanUse / TYPE_SIZE), BUFFER_NUM), ubBlockSize);
223	
224	    // 设置使用的AI Core数量
225	    context->SetBlockDim(usedCoreNum);
226	
227	    // 根据数据类型设置tiling key
228	    uint64_t tilingKey = 0;
229	    if (dataType == ge::DT_FLOAT) {
230	        // 浮点数类型使用mode 0的tiling key
231	        tilingKey = GET_TPL_TILING_KEY(ELEMENTWISE_TPL_SCH_MODE_0);
232	        context->SetTilingKey(tilingKey);
233	    } else if (dataType == ge::DT_INT32) {
234	        // 32位整数类型使用mode 1的tiling key
235	        tilingKey = GET_TPL_TILING_KEY(ELEMENTWISE_TPL_SCH_MODE_1);
236	        context->SetTilingKey(tilingKey);
237	    } else {
238	        OP_LOGE(context, "get dtype error");
239	        return ge::GRAPH_FAILED;
240	    }
241	
242	    return ge::GRAPH_SUCCESS;
243	}
244	
245	/*!
246	 * \brief 解析Add算子的tiling信息
247	 *
248	 * 该函数在模型加载期间被调用，以解析任何静态tiling信息。
249	 * 对于Add算子，不需要静态tiling，因此直接返回成功。
250	 *
251	 * \param context 指向tiling解析上下文的指针
252	 * \return ge::GRAPH_SUCCESS
253	 */
254	static ge::graphStatus TilingParseForAddExample([[maybe_unused]] gert::TilingParseContext* context)
255	{
256	    return ge::GRAPH_SUCCESS;
257	}
258	
259	// tiling注册入口
260	// 将tiling函数、tiling解析函数和编译信息注册到系统中
261	IMPL_OP_OPTILING(AddExample).Tiling(AddExampleTilingFunc).TilingParse<AddExampleCompileInfo>(TilingParseForAddExample);
262	} // namespace optiling
